-- 18.6 builds the added column's index before it checks the column's CHECK: an oversized
-- default that also fails the CHECK is `54000`.
-- @setup
CREATE TABLE t (id int);
INSERT INTO t VALUES (1);
-- @test
-- @expect-error: the index build before the check
-- @expect-message
-- @profile-lock
ALTER TABLE t ADD COLUMN b text UNIQUE CHECK (length(b) < 10) DEFAULT '';
